        super().__init__(
            component_instance=component_instance,
            callbacks=[
                ChimeCallback(
                    changed_elements=component_instance.input_value_map,
                    dom_updates={"sidebar-store": "data"},
                    callback_fn=update_parameters_helper,
                    stores=["sidebar-store"],
                )
            ]
        )


